#include <iostream>
#include <map>
int main() {
    std::multimap<int, std::string> c = {{1, "a"}, {3, "b"}, {3, "c"}, {5, "d"}};
    auto range = c.equal_range(3);
    std::cout << "equal_range(3): " << *range.first->second << " " << *range.second->second << std::endl;
    std::cout << "\nlower_bound(5): " << *c.lower_bound(5) << std::endl;
    std::cout << "upper_bound(5): " << *c.upper_bound(5) << std::endl;
    return 0;
}
